result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/angles.test.mjs", "content": "import test from "node:test";
import assert from "node:assert";
import { clamp, normalizeDeg } from "./angles.mjs";

test("clamp below lo", () => { assert.equal(clamp(-5, 0, 10), 0); });
test("clamp at lo exactly", () => { assert.equal(clamp(0, 0, 10), 0); });
test("clamp middle", () => { assert.equal(clamp(5, 0, 10), 5); });
test("clamp at hi exactly", () => { assert.equal(clamp(10, 0, 10), 10); });
test("clamp above hi", () => { assert.equal(clamp(15, 0, 10), 10); });
test("clamp asymmetric bounds", () => { assert.equal(clamp(7, 3, 8), 7); });

test("normalize -30 wraps to 330", () => { assert.equal(normalizeDeg(-30), 330); });
test("normalize -360 is identity", () => { assert.equal(normalizeDeg(-360), 0); });
test("normalize 0 is identity", () => { assert.equal(normalizeDeg(0), 0); });
test("normalize 360 is identity", () => { assert.equal(normalizeDeg(360), 0); });
test("normalize 180 unchanged", () => { assert.equal(normalizeDeg(180), 180); });
test("normalize 539 wraps to 179", () => { assert.equal(normalizeDeg(539), 179); });
test("normalize large mixed value", () => { assert.equal(normalizeDeg(1095), 15); });
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/mutate.mjs", "content": "// Homemade mutation-testing harness for angles.mjs
//
// Original mutant list:
//   M1: x < lo  -> x <= lo      EQUIVALENT: when x === lo, both variants return lo,
//                               which is exactly clamp's contract value. No input
//                               can distinguish them -> replaced by M1'.
//   M2: return lo -> return hi  (lower branch)
//   M3: x > hi  -> x >= hi      EQUIVALENT: symmetric to M1 at x === hi.
//                               Replaced by M3'.
//   M4: r < 0    -> r > 0
//   M5: r += 360 -> r -= 360
//   M6: a % 360  -> a % 180
//
// Substitute mutants (detectable):
//   M1': final fallthrough "return x;" -> "return lo;"   (in-range values get clamped)
//   M3': upper branch "return hi;"     -> "return lo;"   (over-range values map to lo)

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import fileURLToPath from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const SRC = path.join(here, "angles.mjs");
const TEST = path.join(here, "angles.test.mjs");

const MUTANTS = [
  { id: "M2",  desc: 'lower branch: return lo -> return hi',        from: "if (x < lo) return lo;",  to: "if (x < lo) return hi;" },
  { id: "M4",  desc: "normalizeDeg: r < 0 -> r > 0",                from: "if (r < 0) r += 360;",    to: "if (r > 0) r += 360;" },
  { id: "M5",  desc: "normalizeDeg: r += 360 -> r -= 360",          from: "if (r < 0) r += 360;",    to: "if (r < 0) r -= 360;" },
  { id: "M6",  desc: "normalizeDeg: a % 360 -> a % 180",            from: "let r = a % 360;",        to: "let r = a % 180;" },
  { id: "M1'", desc: "clamp: final return x -> return lo",          from: "return x;",               to: "return lo;" },
  { id: "M3'", desc: "clamp: upper branch return hi -> return lo",  from: "if (x > hi) return hi;",  to: "if (x > hi) return lo;" },
];

const srcCode = fs.readFileSync(SRC, "utf8");
const testCode = fs.readFileSync(TEST, "utf8");

function runSuite(dir) {
  const res = spawnSync("node", ["--test", path.join(dir, "angles.test.mjs")], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  return res.status;
}

// 1) Pristine baseline must pass.
const baselineDir = fs.mkdtempSync(path.join(os.tmpdir(), "mut-pristine-"));
fs.copyFileSync(SRC, path.join(baselineDir, "angles.mjs"));
fs.copyFileSync(TEST, path.join(baselineDir, "angles.test.mjs"));
const baseline = runSuite(baselineDir);
fs.rmSync(baselineDir, { recursive: true, force: true });
console.log(`Pristine suite: ${baseline === 0 ? "PASS" : "FAIL"}\n`);
if (baseline !== 0) {
  console.error("Baseline tests fail; fix tests before mutation testing.");
  process.exit(1);
}

// 2) Run each mutant.
const results = [];
for (const m of MUTANTS) {
  const count = srcCode.split(m.from).length - 1;
  if (count !== 1) {
    throw new Error(`${m.id}: pattern "${m.from}" matched ${count} times, expected exactly 1`);
  }
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), `mut-${m.id}-`));
  // Write mutated module into temp dir...
  fs.writeFileSync(path.join(dir, "angles.mjs"), srcCode.replace(m.from, m.to));
  // ...and rewrite the test's import to point at it.
  const rewritten = testCode.replace(
    /from\s+["']\.\/angles\.mjs["']/,
    `from ${JSON.stringify(path.join(dir, "angles.mjs"))}`
  );
  if (rewritten === testCode) throw new Error("could not rewrite import line");
  fs.writeFileSync(path.join(dir, "angles.test.mjs"), rewritten);

  const status = runSuite(dir);
  results.push({ ...m, killed: status !== 0 });
  fs.rmSync(dir, { recursive: true, force: true });
}

// 3) Report.
const pad = (s, n) => String(s).padEnd(n);
console.log(pad("ID", 5) + pad("MUTATION", 48) + "RESULT");
console.log("-".repeat(65));
for (const r of results) {
  console.log(pad(r.id, 5) + pad(r.desc, 48) + (r.killed ? "KILLED" : "SURVIVED"));
}
const killed = results.filter((r) => r.killed).length;
console.log("-".repeat(65));
console.log(`Mutation score: ${killed}/${results.length}`);

process.exit(killed === results.length && baseline === 0 ? 0 : 1);
"})
print(result)

